"""Byte-level robustness: never crash, always exit 0 with one JSON object."""
import json, random, sys
sys.path.insert(0,'/workspace/tests')
from harness import run_raw
rng = random.Random(99)
seeds = [b'', b' ', b'\n', b'{', b'}', b'[]', b'null', b'true', b'0', b'-0', b'1e999', b'NaN',
         b'{"seed":1}', b'{"seed":"s","timeout_ms":1.5}', b'{"seed":"s","timeout_ms":1,"cases":{}}',
         b'{"seed":"\\ud800x"}', b'{"seed":"s","definitions":[[1,"b\'x\'"]]}',
         b'{"seed":"s","definitions":[["d","b\'x\'"]],"timeout_ms":1,"cases":[],"events":[],"channels":[]}',
         b'\x00\x01\x02', b'{"seed":"s"}\x00', b'{"seed":"s","channels":[{"name":"e"}]}',
         b'{"seed":"s","events":[{"at":1,"kind":"headers","stream":0,"fields":[["a","b"]],"end":true}]}',
         b'{"seed":"s","cases":[{"name":"a","frames":[{"Type":"headers","headers_kv":{":a":"b"}}],"expect":{"method":"G","target":"/","host":"h"}}]}']
fails = 0
for i in range(300):
    raw = rng.choice(seeds)
    mode = rng.randrange(4)
    if mode == 1: raw = raw + bytes(rng.randrange(256) for _ in range(rng.randrange(1,6)))
    elif mode == 2: raw = raw[:rng.randrange(len(raw)+1)]
    elif mode == 3:
        try: obj = json.loads(raw.decode('utf-8','ignore'))
        except Exception: obj = {}
        raw = json.dumps(obj).encode() if isinstance(obj,dict) else raw
    p = run_raw(raw)
    if p.returncode != 0:
        print('FAIL exit', p.returncode, repr(raw[:80]), p.stderr[-300:]); fails += 1; continue
    try:
        out = json.loads(p.stdout.decode())
    except Exception as e:
        print('FAIL json', repr(raw[:80]), p.stdout[:200]); fails += 1; continue
    if not (set(out) in ({'error'}, {'cases','channels'}) and (set(out) != {'error'} or out == {'error':'input'})):
        print('FAIL shape', repr(raw[:80]), p.stdout[:200]); fails += 1
# mutate a valid document in random ways
import itertools
base = {"seed":"s","definitions":[["d","b'ab'"]],"timeout_ms":3,
        "cases":[{"name":"a","frames":[{"Type":"headers","data_to_transfered":[[":method","GET"]],"End_Stream":True}],"expect":{"method":"GET","target":"/","host":"h"}}],
        "events":[{"at":1,"kind":"close"}],
        "channels":[{"name":"e","parts":[{"case":"a","data":"GET / HTTP/1.1\r\nHost: h\r\n\r\n"}]}]}
def mutate(value, depth=0):
    if depth > 3: return value
    kind = rng.randrange(8)
    if kind == 0: return None
    if kind == 1: return rng.choice([1, -1, 1.5, True, "x", [], {}, 2**70])
    if kind == 2 and isinstance(value, dict):
        keys = list(value) + ['zz']
        out = dict(value); out.pop(rng.choice(keys), None); out[rng.choice(keys)] = mutate(None, depth+1)
        return out
    if kind == 3 and isinstance(value, list) and value:
        out = list(value); out[rng.randrange(len(out))] = mutate(out[rng.randrange(len(out))], depth+1); return out
    if kind == 4 and isinstance(value, list):
        return value + [mutate(None, depth+1)]
    if kind == 5 and isinstance(value, str):
        return value + rng.choice(['\x00','\ud800',' ','{{','}}','<<random_string>>','*8192'])
    if kind == 6 and isinstance(value, (int,float)) and not isinstance(value,bool):
        return value * rng.choice([2, -1, 0])
    return value
for i in range(400):
    doc = json.loads(json.dumps(base))
    for _ in range(rng.randrange(1,4)):
        target = rng.choice(['seed','definitions','timeout_ms','cases','events','channels'])
        doc[target] = mutate(doc[target])
    p = run_raw(json.dumps(doc).encode())
    if p.returncode != 0:
        print('FAIL exit', p.returncode, json.dumps(doc)[:200], p.stderr[-300:]); fails += 1; continue
    try:
        out = json.loads(p.stdout.decode())
    except Exception:
        print('FAIL json', json.dumps(doc)[:200], p.stdout[:200]); fails += 1; continue
    if not (set(out) in ({'error'}, {'cases','channels'})):
        print('FAIL shape', json.dumps(doc)[:200], p.stdout[:200]); fails += 1
    if p.stderr:
        print('FAIL stderr', json.dumps(doc)[:120], p.stderr[-200:]); fails += 1
print('FAILS', fails)
